import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import type { NextFunction, Response } from 'express';
import type { AuthRequest } from '../../src/api/middlewares/auth';

const { mockVerifyApiKey } = vi.hoisted(() => ({
  mockVerifyApiKey: vi.fn<(apiKey: string) => Promise<boolean>>(),
}));

vi.mock('@/services/secrets/secret.service.js', () => ({
  SecretService: {
    getInstance: () => ({
      verifyApiKey: mockVerifyApiKey,
    }),
  },
}));

async function loadAuthMiddleware() {
  vi.stubEnv('JWT_SECRET', 'test-secret-long-enough-for-signing-32chars');
  return import('../../src/api/middlewares/auth');
}

describe('verifyApiKey', () => {
  beforeEach(() => {
    vi.resetModules();
    mockVerifyApiKey.mockReset();
  });

  afterEach(() => {
    vi.unstubAllEnvs();
  });

  it('sets hasApiKey only after the API key is verified', async () => {
    mockVerifyApiKey.mockResolvedValue(true);
    const { verifyApiKey } = await loadAuthMiddleware();
    const req = {
      headers: {
        authorization: 'Bearer ik_valid',
      },
    } as AuthRequest;
    const next = vi.fn() as NextFunction;

    await verifyApiKey(req, {} as Response, next);

    expect(mockVerifyApiKey).toHaveBeenCalledWith('ik_valid');
    expect(req.authenticated).toBe(true);
    expect(req.hasApiKey).toBe(true);
    expect(Object.prototype.hasOwnProperty.call(req, 'apiKey')).toBe(false);
    expect(next).toHaveBeenCalledWith();
  });

  it('does not set hasApiKey when API key verification fails', async () => {
    mockVerifyApiKey.mockResolvedValue(false);
    const { verifyApiKey } = await loadAuthMiddleware();
    const req = {
      headers: {
        'x-api-key': 'ik_invalid',
      },
    } as unknown as AuthRequest;
    const next = vi.fn() as NextFunction;

    await verifyApiKey(req, {} as Response, next);

    expect(mockVerifyApiKey).toHaveBeenCalledWith('ik_invalid');
    expect(req.authenticated).toBeUndefined();
    expect(req.hasApiKey).toBeUndefined();
    expect(next).toHaveBeenCalledTimes(1);
    expect(next).toHaveBeenCalledWith(expect.objectContaining({ statusCode: 401 }));
  });
});

import { describe, expect, it } from 'vitest';
import { createSessionRequestSchema, sendOTPRequestSchema } from '@insforge/shared-schemas';

describe('email OTP sign-in schemas', () => {
  it('normalizes email addresses for OTP requests', () => {
    const result = sendOTPRequestSchema.parse({
      email: 'USER@Example.com',
    });

    expect(result).toEqual({ email: 'user@example.com' });
  });

  it('accepts a six-digit OTP and optional first-time profile name', () => {
    const result = createSessionRequestSchema.parse({
      method: 'otp',
      email: 'USER@Example.com',
      otp: '123456',
      name: '  Ada Lovelace  ',
    });

    expect(result).toEqual({
      method: 'otp',
      email: 'user@example.com',
      otp: '123456',
      name: 'Ada Lovelace',
    });
  });

  it('rejects non-numeric or incorrectly sized OTP values', () => {
    expect(
      createSessionRequestSchema.safeParse({
        method: 'otp',
        email: 'user@example.com',
        otp: '12345',
      }).success
    ).toBe(false);
    expect(
      createSessionRequestSchema.safeParse({
        method: 'otp',
        email: 'user@example.com',
        otp: '12345a',
      }).success
    ).toBe(false);
  });

  it('keeps existing password session requests backward compatible', () => {
    const result = createSessionRequestSchema.parse({
      email: 'USER@Example.com',
      password: 'securepassword123',
    });

    expect(result).toEqual({
      method: 'password',
      email: 'user@example.com',
      password: 'securepassword123',
    });
  });

  it('treats a null or undefined method as the legacy password flow', () => {
    for (const method of [null, undefined]) {
      const result = createSessionRequestSchema.parse({
        method,
        email: 'user@example.com',
        password: 'securepassword123',
      });

      expect(result).toMatchObject({ method: 'password', email: 'user@example.com' });
    }
  });

  it('accepts an explicit password method', () => {
    const result = createSessionRequestSchema.parse({
      method: 'password',
      email: 'user@example.com',
      password: 'securepassword123',
    });

    expect(result.method).toBe('password');
  });

  it('preserves field-level errors for legacy password requests', () => {
    const result = createSessionRequestSchema.safeParse({});

    expect(result.success).toBe(false);
    if (!result.success) {
      expect(result.error.issues).toEqual([
        expect.objectContaining({ path: ['email'], message: 'Required' }),
        expect.objectContaining({ path: ['password'], message: 'Required' }),
      ]);
    }
  });

  it('returns OTP field errors for an incomplete OTP request', () => {
    const result = createSessionRequestSchema.safeParse({ method: 'otp' });

    expect(result.success).toBe(false);
    if (!result.success) {
      expect(result.error.issues).toEqual([
        expect.objectContaining({ path: ['email'], message: 'Required' }),
        expect.objectContaining({ path: ['otp'], message: 'Required' }),
      ]);
    }
  });

  it('rejects unknown session methods at the discriminator', () => {
    const result = createSessionRequestSchema.safeParse({ method: 'magic' });

    expect(result.success).toBe(false);
    if (!result.success) {
      expect(result.error.issues).toEqual([
        expect.objectContaining({
          path: ['method'],
          message: "Invalid discriminator value. Expected 'password' | 'otp'",
        }),
      ]);
    }
  });
});

import { describe, it, expect } from 'vitest';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const currentDir = path.dirname(fileURLToPath(import.meta.url));
const migrationPath = path.resolve(
  currentDir,
  '../../src/infra/database/migrations/036_storage-third-party-auth-support.sql'
);

describe('036_storage-third-party-auth-support migration', () => {
  const sql = fs.readFileSync(migrationPath, 'utf8');

  it('migration file exists', () => {
    expect(fs.existsSync(migrationPath)).toBe(true);
  });

  // ── FK drop is idempotent ────────────────────────────────────────────
  it('drops the uploaded_by FK with IF EXISTS', () => {
    expect(sql).toMatch(
      /ALTER TABLE storage\.objects\s+DROP CONSTRAINT IF EXISTS objects_uploaded_by_fkey/i
    );
  });

  // ── Column widen is idempotent ───────────────────────────────────────
  it('guards ALTER COLUMN uploaded_by TYPE TEXT behind information_schema check', () => {
    // Once policies reference uploaded_by, Postgres rejects ALTER TYPE.
    expect(sql).toMatch(
      /information_schema\.columns[\s\S]*?column_name\s*=\s*'uploaded_by'[\s\S]*?<>\s*'text'[\s\S]*?ALTER COLUMN uploaded_by TYPE TEXT/i
    );
  });

  it('does NOT have a bare ALTER COLUMN uploaded_by TYPE TEXT outside a DO block', () => {
    // Strip DO $tag$ ... $tag$ blocks (matched dollar-quoted tags so we
    // don't stop at nested $sql$ ... $sql$ inside).
    const outsideDoBlocks = sql.replace(/DO\s*\$(\w+)\$[\s\S]*?\$\1\$/g, '');
    expect(outsideDoBlocks).not.toMatch(/ALTER COLUMN uploaded_by TYPE TEXT/i);
  });

  // ── Path helpers use CREATE OR REPLACE ───────────────────────────────
  it('defines storage.foldername with CREATE OR REPLACE (replay-safe)', () => {
    expect(sql).toMatch(/CREATE OR REPLACE FUNCTION storage\.foldername/i);
  });

  it('defines storage.filename with CREATE OR REPLACE', () => {
    expect(sql).toMatch(/CREATE OR REPLACE FUNCTION storage\.filename/i);
  });

  it('defines storage.extension with CREATE OR REPLACE', () => {
    expect(sql).toMatch(/CREATE OR REPLACE FUNCTION storage\.extension/i);
  });

  // ── auth.jwt() helper ────────────────────────────────────────────────
  it('defines auth.jwt() with CREATE OR REPLACE', () => {
    expect(sql).toMatch(/CREATE OR REPLACE FUNCTION auth\.jwt\(\)/i);
  });

  it('auth.jwt() reads request.jwt.claims (the GUC withUserContext sets)', () => {
    expect(sql).toMatch(/current_setting\(\s*'request\.jwt\.claims'\s*,\s*true\s*\)/i);
  });

  it('auth.jwt() does NOT read the never-set request.jwt.claim singular form', () => {
    // withUserContext sets request.jwt.claims (jsonb), not a singular request.jwt.claim object.
    expect(sql).not.toMatch(/current_setting\(\s*'request\.jwt\.claim'\s*,/i);
  });

  // ── RLS enablement ───────────────────────────────────────────────────
  it('enables RLS on storage.objects', () => {
    expect(sql).toMatch(/ALTER TABLE storage\.objects ENABLE ROW LEVEL SECURITY/i);
  });

  // ── Policy install is idempotent and gated on existing projects ──────
  it('gates policy install on existing buckets (fresh installs ship deny-by-default)', () => {
    expect(sql).toMatch(/IF EXISTS\s*\(\s*SELECT\s+1\s+FROM\s+storage\.buckets/i);
  });

  // Postgres has no CREATE POLICY IF NOT EXISTS through PG17 — each CREATE
  // must be wrapped in a pg_policy lookup to stay replay-safe.
  it.each([
    'storage_objects_owner_select',
    'storage_objects_owner_insert',
    'storage_objects_owner_update',
    'storage_objects_owner_delete',
  ])('guards CREATE POLICY %s with a pg_policy NOT EXISTS check', (polname) => {
    const guardedRegex = new RegExp(
      `IF NOT EXISTS\\s*\\(\\s*SELECT\\s+1\\s+FROM\\s+pg_policy[\\s\\S]*?polname\\s*=\\s*'${polname}'[\\s\\S]*?CREATE POLICY ${polname}`,
      'i'
    );
    expect(sql).toMatch(guardedRegex);
  });

  it('does NOT have a bare CREATE POLICY outside the guarded DO block', () => {
    // Strip dollar-quoted DO blocks (matched tags so $sql$ inside doesn't
    // close $migration$ early) and -- line comments before the assertion.
    const stripped = sql.replace(/DO\s*\$(\w+)\$[\s\S]*?\$\1\$/g, '').replace(/^\s*--.*$/gm, '');
    expect(stripped).not.toMatch(/CREATE POLICY/i);
  });

  it("uses (SELECT auth.jwt() ->> 'sub') hoisted form (cached once per query)", () => {
    const matches = sql.match(/\(\s*SELECT\s+auth\.jwt\(\)\s*->>\s*'sub'\s*\)/gi);
    expect(matches?.length ?? 0).toBeGreaterThanOrEqual(4);
  });

  // ── Grants ───────────────────────────────────────────────────────────
  it('grants storage.objects DML to authenticated', () => {
    expect(sql).toMatch(
      /GRANT\s+SELECT,\s*INSERT,\s*UPDATE,\s*DELETE\s+ON\s+storage\.objects\s+TO\s+authenticated/i
    );
  });

  it('grants USAGE on schema storage to authenticated', () => {
    expect(sql).toMatch(/GRANT\s+USAGE\s+ON\s+SCHEMA\s+storage\s+TO\s+authenticated/i);
  });

  it('grants EXECUTE on auth.jwt() to authenticated and anon', () => {
    expect(sql).toMatch(
      /GRANT\s+EXECUTE\s+ON\s+FUNCTION\s+auth\.jwt\(\)\s+TO\s+authenticated,\s*anon/i
    );
  });

  // ── Ordering ─────────────────────────────────────────────────────────
  it('runs after migration 035', () => {
    const migrationDir = path.resolve(currentDir, '../../src/infra/database/migrations');
    const migrations = fs
      .readdirSync(migrationDir)
      .filter((file) => file.endsWith('.sql'))
      .sort();

    const idx036 = migrations.indexOf('036_storage-third-party-auth-support.sql');
    expect(idx036).toBeGreaterThanOrEqual(0);
    const earlierMigrations = migrations.filter((m) => m.startsWith('035_'));
    if (earlierMigrations.length > 0) {
      const idx035 = migrations.indexOf(earlierMigrations[0]);
      expect(idx036).toBeGreaterThan(idx035);
    }
  });
});

import { beforeAll, beforeEach, describe, expect, it, vi } from 'vitest';
import type { NextFunction, Request, Response, Router } from 'express';

interface RouteError {
  statusCode: number;
  code: string;
  message: string;
}

const mocks = vi.hoisted(() => ({
  sendSignInOTP: vi.fn(),
  signInWithOTP: vi.fn(),
  login: vi.fn(),
  verifyOTPRequest: vi.fn(),
  generateRefreshToken: vi.fn(),
  generateRefreshTokenWithCsrf: vi.fn(),
}));

vi.mock('@/services/auth/auth.service.js', () => ({
  AuthService: {
    getInstance: () => ({
      sendSignInOTP: mocks.sendSignInOTP,
      signInWithOTP: mocks.signInWithOTP,
      login: mocks.login,
    }),
  },
}));

vi.mock('@/api/middlewares/rate-limiters.js', () => ({
  idTokenSignInRateLimiter: (_req: Request, _res: Response, next: NextFunction) => next(),
  sendEmailOTPLimiter: [(_req: Request, _res: Response, next: NextFunction) => next()],
  verifyOTPLimiter: [(_req: Request, _res: Response, next: NextFunction) => next()],
  verifyOTPRateLimiter: (req: Request, _res: Response, next: NextFunction) => {
    mocks.verifyOTPRequest(req.body);
    next();
  },
}));

vi.mock('@/infra/security/token.manager.js', () => ({
  TokenManager: {
    getInstance: () => ({
      verifyToken: vi.fn(),
      generateAccessToken: vi.fn(),
      generateRefreshToken: mocks.generateRefreshToken,
      generateRefreshTokenWithCsrf: mocks.generateRefreshTokenWithCsrf,
    }),
  },
}));

vi.mock('@/utils/logger.js', () => ({
  default: { info: vi.fn(), error: vi.fn(), warn: vi.fn(), debug: vi.fn() },
}));

const SESSION = {
  user: {
    id: '11111111-1111-4111-8111-111111111111',
    email: 'user@example.com',
    emailVerified: true,
    providers: [],
    createdAt: '2026-01-01T00:00:00.000Z',
    updatedAt: '2026-01-01T00:00:00.000Z',
    profile: {},
    metadata: {},
  },
  accessToken: 'access-token',
};

function callRoute(
  router: Router,
  path: string,
  body: Record<string, unknown>,
  query: Record<string, string> = {}
): Promise<{ statusCode: number; body: unknown; cookie: ReturnType<typeof vi.fn> }> {
  return new Promise((resolve) => {
    let statusCode = 200;
    const cookie = vi.fn();
    const req: Partial<Request> = {
      url: path,
      method: 'POST',
      headers: {},
      query,
      body,
    };
    const res: Partial<Response> = {
      status: vi.fn((code: number) => {
        statusCode = code;
        return res;
      }),
      json: vi.fn((data: unknown) => resolve({ statusCode, body: data, cookie })),
      cookie: vi.fn((...args: unknown[]) => {
        cookie(...args);
        return res;
      }),
    };

    router(
      req as Request,
      res as Response,
      vi.fn((error?: unknown) => {
        if (error && typeof error === 'object' && 'statusCode' in error) {
          const routeError = error as RouteError;
          resolve({
            statusCode: routeError.statusCode,
            body: {
              error: routeError.code,
              message: routeError.message,
              statusCode: routeError.statusCode,
            },
            cookie,
          });
        }
      })
    );
  });
}

describe('email OTP auth routes', () => {
  let router: Router;

  beforeAll(async () => {
    router = (await import('../../src/api/routes/auth/index.routes.js')).default;
  });

  beforeEach(() => {
    vi.clearAllMocks();
    mocks.sendSignInOTP.mockResolvedValue(undefined);
    mocks.signInWithOTP.mockResolvedValue({ ...SESSION });
    mocks.login.mockResolvedValue({ ...SESSION });
    mocks.generateRefreshToken.mockReturnValue('refresh-token');
    mocks.generateRefreshTokenWithCsrf.mockReturnValue({
      refreshToken: 'refresh-token',
      csrfToken: 'csrf-token',
    });
  });

  it('accepts an email OTP request without requiring an existing user', async () => {
    const response = await callRoute(router, '/email/send-otp', {
      email: 'USER@Example.com',
    });

    expect(response.statusCode).toBe(202);
    expect(response.body).toMatchObject({ success: true });
    expect(mocks.sendSignInOTP).toHaveBeenCalledWith('user@example.com');
  });

  it('creates a web session with the OTP method through the existing cookie convention', async () => {
    const response = await callRoute(router, '/sessions', {
      method: 'otp',
      email: 'user@example.com',
      otp: '123456',
      name: 'Ada',
    });

    expect(response.statusCode).toBe(200);
    expect(response.body).toMatchObject({
      accessToken: 'access-token',
      csrfToken: 'csrf-token',
    });
    expect(mocks.signInWithOTP).toHaveBeenCalledWith('user@example.com', '123456', 'Ada');
    expect(mocks.verifyOTPRequest).toHaveBeenCalledOnce();
    expect(mocks.generateRefreshTokenWithCsrf).toHaveBeenCalledWith(SESSION.user.id, 'user');
  });

  it('returns a refresh token in the body for native OTP clients', async () => {
    const response = await callRoute(
      router,
      '/sessions',
      { method: 'otp', email: 'user@example.com', otp: '123456' },
      { client_type: 'mobile' }
    );

    expect(response.body).toMatchObject({ refreshToken: 'refresh-token' });
    expect(mocks.generateRefreshToken).toHaveBeenCalledWith(SESSION.user.id, 'user');
  });

  it('keeps password sessions backward compatible without method or OTP rate limiting', async () => {
    const response = await callRoute(router, '/sessions', {
      email: 'user@example.com',
      password: 'securepassword123',
    });

    expect(response.statusCode).toBe(200);
    expect(mocks.login).toHaveBeenCalledWith('user@example.com', 'securepassword123');
    expect(mocks.signInWithOTP).not.toHaveBeenCalled();
    expect(mocks.verifyOTPRequest).not.toHaveBeenCalled();
  });

  it('dispatches an explicit password method without OTP rate limiting', async () => {
    const response = await callRoute(router, '/sessions', {
      method: 'password',
      email: 'user@example.com',
      password: 'securepassword123',
    });

    expect(response.statusCode).toBe(200);
    expect(mocks.login).toHaveBeenCalledWith('user@example.com', 'securepassword123');
    expect(mocks.verifyOTPRequest).not.toHaveBeenCalled();
  });

  it('preserves legacy field-level errors for an empty session request', async () => {
    const response = await callRoute(router, '/sessions', {});

    expect(response.statusCode).toBe(400);
    expect(response.body).toMatchObject({
      error: 'INVALID_INPUT',
      message: 'email: Required, password: Required',
    });
  });

  it('returns OTP field-level errors for an incomplete OTP session request', async () => {
    const response = await callRoute(router, '/sessions', { method: 'otp' });

    expect(response.statusCode).toBe(400);
    expect(response.body).toMatchObject({
      error: 'INVALID_INPUT',
      message: 'email: Required, otp: Required',
    });
    expect(mocks.verifyOTPRequest).toHaveBeenCalledOnce();
    expect(mocks.signInWithOTP).not.toHaveBeenCalled();
  });
});

/**
